// Ported from the Node app's Sequelize model LeaveType (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class LeaveTypeConfiguration : IEntityTypeConfiguration<LeaveType>
{
    public void Configure(EntityTypeBuilder<LeaveType> builder)
    {
        builder.ToTable("leave_types", t =>
        {
            t.HasCheckConstraint("CK_leave_types_applies_to", "[applies_to] IN (N'staff', N'student', N'both')");
            t.HasCheckConstraint("CK_leave_types_approver", "[approver] IN (N'admin', N'class_teacher', N'department_head')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(60)").HasMaxLength(60).IsRequired();
        builder.Property(e => e.AppliesTo).HasColumnName("applies_to").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'staff'");
        builder.Property(e => e.YearlyDays).HasColumnName("yearly_days");
        builder.Property(e => e.Paid).HasColumnName("paid");
        builder.Property(e => e.Approver).HasColumnName("approver").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'admin'");
        builder.Property(e => e.AutoApproveDays).HasColumnName("auto_approve_days");
        builder.Property(e => e.Active).HasColumnName("active");
        builder.HasIndex(e => e.Name).IsUnique();
    }
}
